//! The scripts the preview runs *inside* the pod. They live under
//! `/home/.noite/preview/` — beside Noite's metadata and outside the
//! checkout — because a file in the user's tree would show up as a change and
//! get pushed. Poder's built ESM and the assets shim are written verbatim;
//! the server that ties them together is generated from the checkout's
//! config.
//!
//! The server is plain ESM: the pod strips TypeScript, but the less of its
//! transform a generated file depends on, the fewer ways it can surprise.
import type { WorkspaceFs } from "../workspace/types";
import { PODER_SOURCES } from "./poder-source";
import { serverSource } from "./server";
import type { HarnessPlan } from "./server";
import { SHIM_SOURCES } from "./shims-source";

/** Where the preview's own files live in the pod. */
export const HARNESS_DIR = "/home/.noite/preview";

/** Poder's built ESM, as the generated server imports it. */
export const PODER_DIR = `${HARNESS_DIR}/poder`;

/** The `cloudflare:workers` shim: the Worker bundle's `cloudflare:workers`
 * imports are aliased here when the entry is bundled. */
export const PODER_WORKERS_SHIM = `${PODER_DIR}/cloudflare-workers.mjs`;

/** Build output, skipped by the workspace's persistence. */
export const HARNESS_CACHE_DIR = `${HARNESS_DIR}/.cache`;
/** The generated server, spawned once per preview start. */
export const HARNESS_SERVER = `${HARNESS_DIR}/serve.ts`;

/** The harness directory's marker. The pod decides a module's kind by the
 * nearest `package.json`; without this one — the harness lives outside the
 * checkout, under `/home` — every module is read as CommonJS and dies on
 * its first `export`. */
export const HARNESS_MANIFEST = `${HARNESS_DIR}/package.json`;

/** The Vite configs of the plugin-less build: the client bundle beside the
 * server, the Worker's SSR bundle beside that. */
export const HARNESS_CLIENT_DIR = `${HARNESS_CACHE_DIR}/client`;
export const HARNESS_WORKER_DIR = `${HARNESS_CACHE_DIR}/worker`;
export const HARNESS_WORKER_CONFIG = `${HARNESS_DIR}/vite.worker.config.mjs`;
export const HARNESS_CLIENT_CONFIG = `${HARNESS_DIR}/vite.client.config.mjs`;

/** Write Poder, the remaining shim and the generated server into the pod,
 * and answer with the server's path. A preview with a Worker entry refuses
 * to start without Poder's dist: importing a missing module would fail at
 * spawn time instead, with the pod's own wording. */
export const writeHarness = async (
  fs: WorkspaceFs,
  plan: HarnessPlan
): Promise<string> => {
  if (plan.entry !== null && PODER_SOURCES["index.mjs"] === undefined) {
    throw new Error(
      "preview: Poder's dist is not in the bundle (copy packages/poder/dist into apps/noite/poder-dist — see poder-source.ts)"
    );
  }
  await fs.mkdir(`${HARNESS_DIR}/shims`, { recursive: true });
  await fs.mkdir(PODER_DIR, { recursive: true });
  // The tooling install wrote the manifest with its dependencies; only a mode
  // without tooling needs the bare marker.
  if (!(await fs.exists(HARNESS_MANIFEST))) {
    await fs.writeFile(
      HARNESS_MANIFEST,
      `${JSON.stringify({ name: "noite-preview", private: true, type: "module" }, null, 2)}\n`
    );
  }
  await Promise.all([
    ...Object.entries(PODER_SOURCES).map(([name, source]) =>
      fs.writeFile(`${PODER_DIR}/${name}`, source)
    ),
    ...Object.entries(SHIM_SOURCES).map(([name, source]) =>
      fs.writeFile(`${HARNESS_DIR}/shims/${name}`, source)
    ),
  ]);
  await fs.writeFile(HARNESS_SERVER, serverSource(plan));
  return HARNESS_SERVER;
};

/** The plugin-less Vite build: a client config (the app's `index.html`, its
 * own Vite config and every plugin it adds are left out) and a Worker config
 * (the entry as an SSR build in ES module form, with the Worker's
 * `cloudflare:workers` imports aliased at Poder's shim). Both are plain
 * objects with no imports: they live outside the checkout, where a bare
 * `vite` import would not resolve, and Vite accepts a config object as-is. */
export const writeViteConfigs = async (
  fs: WorkspaceFs,
  entry: string
): Promise<{
  client: string;
  clientDir: string;
  worker: string;
  workerDir: string;
}> => {
  await fs.mkdir(HARNESS_CACHE_DIR, { recursive: true });
  await fs.writeFile(
    HARNESS_CLIENT_CONFIG,
    `// Generated by Noite's Preview panel: the client half, without the app's plugins.
export default {
  build: {
    emptyOutDir: true,
    outDir: ${JSON.stringify(HARNESS_CLIENT_DIR)},
    target: "esnext",
  },
  root: "/home/project",
};
`
  );
  await fs.writeFile(
    HARNESS_WORKER_CONFIG,
    `// Generated by Noite's Preview panel: the Worker half, as an ES module.
export default {
  build: {
    emptyOutDir: true,
    minify: false,
    outDir: ${JSON.stringify(HARNESS_WORKER_DIR)},
    rollupOptions: { output: { entryFileNames: "index.js", format: "es" } },
    ssr: ${JSON.stringify(entry)},
    target: "esnext",
  },
  resolve: {
    alias: { "cloudflare:workers": ${JSON.stringify(PODER_WORKERS_SHIM)} },
  },
  root: "/home/project",
};
`
  );
  return {
    client: HARNESS_CLIENT_CONFIG,
    clientDir: HARNESS_CLIENT_DIR,
    worker: HARNESS_WORKER_CONFIG,
    workerDir: HARNESS_WORKER_DIR,
  };
};
